from itertools import permutations

def count_distinct_strings(grid):
    N = len(grid[0])
    # Create a graph where each cell is a node and edges represent possible moves
    graph = {(i, j): [] for i in range(2) for j in range(N)}
    for i in range(2):
        for j in range(N):
            if j > 0:
                graph[(i, j)].append((i, j - 1))
            if j < N - 1:
                graph[(i, j)].append((i, j + 1))
            if i == 0:
                graph[(i, j)].append((1, j))
            elif i == 1:
                graph[(i, j)].append((0, j))

    # Function to find all Hamiltonian paths in the graph
    def find_paths(graph, start):
        paths = []
        stack = [(start, [start])]
        while stack:
            (node, path) = stack.pop()
            if len(path) == len(graph):
                paths.append(path)
            else:
                for neighbor in graph[node]:
                    if neighbor not in path:
                        stack.append((neighbor, path + [neighbor]))
        return paths

    # Find all Hamiltonian paths starting from each cell
    all_paths = set()
    for i in range(2):
        for j in range(N):
            paths = find_paths(graph, (i, j))
            for path in paths:
                all_paths.add(''.join(grid[x][y] for x, y in path))

    return len(all_paths)

